package com.ibrowser.download

import android.os.Handler
import android.os.Looper
import android.util.Base64
import android.webkit.MimeTypeMap
import android.webkit.WebView
import java.io.File
import java.io.FileOutputStream
import java.net.URLDecoder
import java.util.UUID
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.Executors

/**
 * Saves files that only exist inside a web page:
 *  - `blob:` URLs (generated by JavaScript — converters, editors, chat exports, cloud drives)
 *    are read inside the page in 512 KB chunks and streamed to disk through the JS bridge;
 *  - `data:` URLs are decoded directly.
 * The page script (inject.js) keeps blobs alive after `revokeObjectURL` and remembers the
 * name from `<a download="…">`, so the saved file gets the name the site intended.
 */
object PageFileSaver {
    private class Session(val item: DownloadItem, val part: File, val out: FileOutputStream, val target: File)

    private val sessions = ConcurrentHashMap<String, Session>()
    private val io = Executors.newSingleThreadExecutor()
    private val main = Handler(Looper.getMainLooper())

    // ------------------------------------------------------------ data:
    fun saveDataUrl(url: String, nameHint: String?, onDone: (DownloadItem) -> Unit) {
        io.execute {
            val header = url.removePrefix("data:").substringBefore(',')
            val payload = url.substringAfter(',', "")
            val mime = header.substringBefore(';').ifBlank { "text/plain" }
            val bytes = runCatching {
                if (header.contains(";base64", true)) Base64.decode(payload, Base64.DEFAULT)
                else URLDecoder.decode(payload, "UTF-8").toByteArray()
            }.getOrNull()
            val name = finalName(nameHint, mime)
            val target = DownloadManager.uniqueFile(name)
            val item = DownloadItem(UUID.randomUUID().toString().take(12), "data:$mime", target.name, DlKind.BLOB, mime, null, null, 1)
            if (bytes == null) {
                item.status = DlStatus.FAILED; item.error = "Couldn't read the file data"
            } else {
                target.writeBytes(bytes)
                item.path = target.absolutePath; item.total = bytes.size.toLong(); item.downloaded = item.total
                item.status = DlStatus.COMPLETED; item.resumable = false
            }
            main.post { DownloadManager.add(item); onDone(item) }
        }
    }

    private fun finalName(hint: String?, mime: String?): String {
        val ext = mime?.let { MimeTypeMap.getSingleton().getExtensionFromMimeType(it.substringBefore(';').trim()) }
        var n = LinkResolver.sanitize(hint?.takeIf { it.isNotBlank() } ?: "download")
        if (!n.contains('.') && ext != null) n = "$n.$ext"
        return n
    }

    // ------------------------------------------------------------ blob:
    /** Starts reading [blobUrl] inside [webView]'s page; progress shows in the Downloads list. */
    fun saveBlob(webView: WebView, blobUrl: String, mimeHint: String?, nameHint: String?, pageUrl: String?) {
        val id = UUID.randomUUID().toString().take(12)
        val js = """
            (async function(){
              var id='$id', url=${jsString(blobUrl)};
              var N=window.iBrowserNative;
              try {
                var b = (window.__ibBlobs && window.__ibBlobs[url]) || null;
                if (!b) { var r = await fetch(url); b = await r.blob(); }
                var name = (window.__ibLastDl && window.__ibLastDl.href === url) ? window.__ibLastDl.name : '';
                N.blobStart(id, b.size, b.type || '', name || '');
                var CH = 512*1024;
                for (var o = 0; o < b.size; o += CH) {
                  var u = new Uint8Array(await b.slice(o, o + CH).arrayBuffer());
                  var s = '';
                  for (var i = 0; i < u.length; i += 0x8000) s += String.fromCharCode.apply(null, u.subarray(i, i + 0x8000));
                  N.blobChunk(id, btoa(s));
                }
                N.blobEnd(id, '');
              } catch (e) { try { N.blobStart(id, 0, '', ''); } catch (x) {} N.blobEnd(id, String(e && e.message || e)); }
            })();
        """.trimIndent()
        pending[id] = Pending(mimeHint, nameHint, pageUrl)
        webView.evaluateJavascript(js, null)
    }

    private class Pending(val mime: String?, val name: String?, val page: String?)
    private val pending = ConcurrentHashMap<String, Pending>()

    private fun jsString(s: String) = "'" + s.replace("\\", "\\\\").replace("'", "\\'") + "'"

    /** Called from the JS bridge (binder thread). */
    fun start(id: String, size: Long, mime: String, pageName: String) {
        val p = pending.remove(id)
        val m = mime.ifBlank { p?.mime ?: "application/octet-stream" }
        val name = finalName(pageName.ifBlank { p?.name?.takeIf { it != "download" && it.isNotBlank() } ?: "download" }, m)
        val target = DownloadManager.uniqueFile(name)
        val part = File(target.absolutePath + ".part")
        val item = DownloadItem(id, "blob:" + (p?.page ?: ""), target.name, DlKind.BLOB, m, null, p?.page, 1)
        item.total = size; item.status = DlStatus.RUNNING; item.resumable = false; item.activeThreads = 1
        item.detail = "Saving file from the page"
        sessions[id] = Session(item, part, FileOutputStream(part), target)
        main.post { DownloadManager.add(item) }
    }

    fun chunk(id: String, b64: String) {
        val s = sessions[id] ?: return
        val bytes = Base64.decode(b64, Base64.DEFAULT)
        s.out.write(bytes)
        main.post { s.item.downloaded += bytes.size }
    }

    fun end(id: String, error: String) {
        val s = sessions.remove(id) ?: run {
            if (error.isNotBlank()) com.ibrowser.browser.Browser.toast("Couldn't save the file: $error")
            return
        }
        runCatching { s.out.close() }
        main.post {
            if (error.isBlank() && s.part.renameTo(s.target)) {
                s.item.path = s.target.absolutePath
                s.item.downloaded = s.target.length(); s.item.total = s.item.downloaded
                s.item.status = DlStatus.COMPLETED; s.item.detail = ""
                DownloadManager.onExternalComplete(s.item)
            } else {
                s.part.delete()
                s.item.status = DlStatus.FAILED
                s.item.error = if (error.isNotBlank()) "The page no longer has this file ($error) — tap its download button again" else "Couldn't write the file"
                DownloadManager.save()
            }
        }
    }
}
